import { readFile, writeFile } from 'node:fs/promises'
import path from 'node:path'

const outputDir = path.resolve(process.argv[2] || 'assets/shiki')

async function main() {
  const languagesManifest = await readManifest(path.join(outputDir, 'languages', 'manifest.fkindex'), 'language')
  const themesManifest = await readManifest(path.join(outputDir, 'themes', 'manifest.fkindex'), 'theme')
  const source = [
    '// Generated by scripts/generate-ferriki-catalog.mjs; do not edit by hand.',
    `export const ferrikiCatalogVersion = 1`,
    `export const languageCatalog = Object.freeze(${JSON.stringify(languagesManifest.entries, null, 2)})`,
    `export const themeCatalog = Object.freeze(${JSON.stringify(themesManifest.entries, null, 2)})`,
    '',
  ].join('\n')

  await writeFile(path.join(outputDir, 'catalog.mjs'), source, 'utf8')
}

function readManifest(file, kind) {
  return readFile(file).then(bytes => {
    const cursor = new Cursor(bytes, file)
    const formatVersion = cursor.u32()
    const source = {
      upstream: cursor.string(),
      version: cursor.optionalString(),
      commit: cursor.optionalString(),
    }
    const entries = Array.from({ length: cursor.u64() }, () => (
      kind === 'language' ? readLanguageEntry(cursor) : readThemeEntry(cursor)
    ))
    cursor.assertEnd()
    return { formatVersion, source, entries }
  })
}

function readLanguageEntry(cursor) {
  return {
    id: cursor.string(),
    scopeName: cursor.string(),
    assetFile: cursor.string(),
    displayName: cursor.optionalString(),
    aliases: cursor.strings(),
    embeddedLangs: cursor.strings(),
    embeddedLangsLazy: cursor.strings(),
    injectTo: cursor.strings(),
  }
}

function readThemeEntry(cursor) {
  return {
    id: cursor.string(),
    assetFile: cursor.string(),
    displayName: cursor.optionalString(),
    themeType: cursor.optionalString(),
  }
}

class Cursor {
  constructor(bytes, file) {
    this.bytes = bytes
    this.file = file
    this.offset = 0
    this.view = new DataView(bytes.buffer, bytes.byteOffset, bytes.byteLength)
  }

  u8() {
    this.ensure(1)
    return this.view.getUint8(this.offset++)
  }

  u32() {
    this.ensure(4)
    const value = this.view.getUint32(this.offset, true)
    this.offset += 4
    return value
  }

  u64() {
    this.ensure(8)
    const value = this.view.getBigUint64(this.offset, true)
    this.offset += 8
    if (value > BigInt(Number.MAX_SAFE_INTEGER))
      throw new Error(`Length in ${this.file} exceeds JavaScript's safe integer range`)
    return Number(value)
  }

  string() {
    const length = this.u64()
    this.ensure(length)
    const value = new TextDecoder().decode(this.bytes.subarray(this.offset, this.offset + length))
    this.offset += length
    return value
  }

  optionalString() {
    return this.u8() === 0 ? null : this.string()
  }

  strings() {
    return Array.from({ length: this.u64() }, () => this.string())
  }

  ensure(length) {
    if (this.offset + length > this.bytes.byteLength)
      throw new Error(`Truncated Ferriki manifest ${this.file} at byte ${this.offset}`)
  }

  assertEnd() {
    if (this.offset !== this.bytes.byteLength)
      throw new Error(`Unexpected trailing data in Ferriki manifest ${this.file}`)
  }
}

await main()
